import "server-only";
import { auth } from "@/auth";
import type { Prisma } from "@/generated/prisma/client";
import { adminDb } from "./db";
import { AdminError, uuid } from "./contracts";
const adminActorSelect = {
  id: true,
  isAdmin: true,
  isSuspended: true,
  deletionRequestedAt: true,
} as const;
import { freshAuthentication } from "./auth-freshness";
export { freshAuthentication } from "./auth-freshness";
export async function checkActor(tx: Prisma.TransactionClient, userId: string) {
  const user = await tx.user.findUnique({
    where: { id: userId },
    select: adminActorSelect,
  });
  if (!user?.isAdmin || user.isSuspended || user.deletionRequestedAt)
    throw new AdminError("DENIED");
  return user;
}
export async function requireAdmin(mutation = false) {
  try {
    const session = await auth();
    if (!uuid.safeParse(session?.user?.id).success)
      throw new AdminError("DENIED");
    const database = adminDb();
    // Fail closed for a misconfigured owner URL or inherited PUBLIC grants.
    const boundary = await database.$queryRaw<{ restricted: boolean }[]>`
      SELECT NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls))
      AND NOT has_column_privilege(current_user, '"User"', 'encryptedRefreshToken', 'SELECT')
      AND NOT has_column_privilege(current_user, '"User"', 'googleId', 'SELECT')
      AND NOT has_column_privilege(current_user, '"User"', 'isAdmin', 'UPDATE')
      AND NOT has_column_privilege(current_user, '"Send"', 'body', 'SELECT')
      AND NOT has_column_privilege(current_user, '"Send"', 'subject', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Contact"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Template"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Attachment"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"BillingWebhookEvent"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"AccountDeletionJob"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"AdminAuditLog"', 'SELECT') AS restricted`;
    if (!boundary[0]?.restricted) throw new AdminError("UNAVAILABLE");
    const actor = await checkActor(database, session!.user.id);
    if (
      mutation &&
      (!freshAuthentication(session!.adminAuthAt) ||
        session!.adminAuthUserId !== actor.id)
    )
      throw new AdminError("REAUTH_REQUIRED");
    return { ...actor, authenticatedAt: session!.adminAuthAt };
  } catch (error) {
    if (error instanceof AdminError) throw error;
    throw new AdminError("UNAVAILABLE");
  }
}
